-- Исправление: убираем отдельную главу «Методическое пособие ФАР»
-- и вместо этого обогащаем существующую Главу 14 детальным контентом из книги.

DO $$
DECLARE
  ch14_id uuid;
  psr_ch_id uuid;
  s_id uuid;
BEGIN

-- 1. Удаляем новую главу и все её узлы (из миграции 021)
DELETE FROM kg_edges
WHERE source_node_id IN (
  SELECT id FROM kg_nodes WHERE parent_id = (
    SELECT id FROM kg_nodes WHERE title = 'Методическое пособие ФАР: ПСР в малой группе' LIMIT 1
  )
)
OR target_node_id IN (
  SELECT id FROM kg_nodes WHERE parent_id = (
    SELECT id FROM kg_nodes WHERE title = 'Методическое пособие ФАР: ПСР в малой группе' LIMIT 1
  )
);

DELETE FROM kg_edges
WHERE source_node_id = (SELECT id FROM kg_nodes WHERE title = 'Методическое пособие ФАР: ПСР в малой группе' LIMIT 1)
   OR target_node_id = (SELECT id FROM kg_nodes WHERE title = 'Методическое пособие ФАР: ПСР в малой группе' LIMIT 1);

DELETE FROM kg_nodes WHERE parent_id = (
  SELECT id FROM kg_nodes WHERE title = 'Методическое пособие ФАР: ПСР в малой группе' LIMIT 1
);

DELETE FROM kg_nodes WHERE title = 'Методическое пособие ФАР: ПСР в малой группе';

-- 2. Находим Главу 14
SELECT id INTO ch14_id FROM kg_nodes
WHERE title = 'Глава 14. Спасательные работы в малой группе' LIMIT 1;

-- 3. Обновляем существующие разделы Главы 14 с богатым контентом из книги

UPDATE kg_nodes SET content =
'Три базовых сценария ПСР в малой группе: срыв лидера, пострадавший на маршруте, падение в трещину. Алгоритм первых действий: оценить обстановку → обеспечить свою безопасность → организовать страховку → подойти к пострадавшему → оказать помощь. Приоритет — скорость и безопасность: медленно и правильно лучше, чем быстро и с ошибкой. Спасатель действует один при минимуме снаряжения — знание полного набора технических приёмов обязательно. Источник: С. Веденин «ПСР в малой группе», ФАР 2014.'
WHERE title = '14.1. Стратегия и тактика';

UPDATE kg_nodes SET content =
'Узлы для ПСР из книги С. Веденина (ФАР 2014): Восьмёрка — привязывание к верёвке и станции. Грейпвайн — связывание двух верёвок. УИАА — спуск и динамическая страховка через карабин. Мунтер-мула — ключевой узел ПСР: блокирует нагрузку с возможностью снятия под нагрузкой. Вай нот — дополнительный стопор (всегда вязать рядом со схватывающим). Схватывающий прусик (3 оборота, 7-мм репшнур) — самостраховка и подъём по верёвке. Французский схватывающий — легче ослабляется под нагрузкой, рекомендуется для страховки при спуске. Узел Гарда — блокировка обратного хода полиспаста. Барел — соединение верёвок разного диаметра. Стремя — педаль при подъёме на схватывающих.'
WHERE title = '14.2. Узлы для спасработ';

UPDATE kg_nodes SET content =
'Два базовых сценария. (1) При нижней страховке, срыв лидера выше станции: блокировать страховочное устройство → схватывающий узел с «вай нот» на грузовой верёвке → Мунтер-мула на станцию → перенести нагрузку → снять устройство. (2) Срыв лидера в начале лазанья, падение ниже станции (фактор рывка 2 — особо опасно!): Вариант А (спасатель близко) — схватывающий через корделет + Мунтер-мула на станцию; Вариант Б (спасатель далеко) — схватывающий на двойной верёвке (самостраховка + свободный конец) + Мунтер-мула на станцию. После освобождения от страховки организовать новую самостраховку! Для разблокировки ATC в режиме автоблокировки: через отверстие-рычаг (Метод 1) или корделет через карабин удержания верёвки в карабин станции (Метод 2).'
WHERE title = '14.3. Передача страховки на станцию';

UPDATE kg_nodes SET content =
'Три варианта спуска пострадавшего. (1) Без сопровождения: пострадавший в сознании. Спусковая система на узле УИАА (на тонких/обледенелых — двойной УИАА). Страховка: схватывающий + «вай нот» через Мунтер-мула. ВНИМАНИЕ: стандартные устройства (восьмёрка, ATC) без дополнительного перегиба верёвки опасны! (2) С наращиванием верёвки: два независимых спусковых устройства на станции. При приближении узла: нагрузку на схватывающий → верёвку из первого устройства → Мунтер-мула разблокировать → нагрузку на второе. (3) С сопровождающим: привязь сопровождающего на 15–20 см короче. Корделет «парсел-прусик». Транспортировка: тяжёлые травмы — перед собой, травмы ног — на спине, при сознании — рядом. Переход через карниз — максимальная осторожность, ноги перестанут касаться рельефа. Система «тандем-противовес» — для подхода к пострадавшему при страховке через ATC в режиме автоблокировки.'
WHERE title = '14.4. Спуск пострадавшего';

UPDATE kg_nodes SET content =
'Подъём по верёвке с помощью двух схватывающих узлов: верхний — в страховочную систему через муфтованный карабин, нижний — «педаль» через узел стремя. Длина петли подбирается так, чтобы узел в ненагруженном состоянии был у локтя поднятой руки. Z-полиспаст 3:1: организуется за 1 минуту при страховке через ATC в автоблокировке. Реальный выигрыш без ролика: 1,75:1–2,19:1; с роликом — значительно выше. Переход к 5:1: один карабин + корделет. Переход к 7:1: ещё один карабин + корделет. Мини-полиспаст — для подъёма на несколько сантиметров (2–3 витка корделета через 2 карабина). Тянуть равномерно, без рывков — рывки расшатывают станцию и могут травмировать пострадавшего. ЗАПРЕЩЕНО использовать «оборотный» карабин — он нивелирует выигрыш. При подъёме с сопровождающим организуется такая же система подвески, как при спуске.'
WHERE title = '14.5. Подъём пострадавшего';

UPDATE kg_nodes SET content =
'Типичные проблемы и решения при ПСР в малой группе. Зависание при спуске: подойти → мини-полиспаст для разгрузки схватывающего → продолжить спуск (в реальных условиях — отрезать схватывающий, не задев грузовую верёвку). Зависание при подъёме: подойти → убрать ненагруженный зажим/схватывающий → установить спусковое устройство ниже нагруженного → организовать сопровождение. Спуск по верёвке без страховочной системы: АВАРИЙНЫЙ метод, только для пологого рельефа — верёвка обводится вокруг корпуса и ног, контроль рукой. Освобождение от зависания при подъёме пострадавшего: снять ненагруженный элемент → установить спусковое устройство → переложить нагрузку. Минимальный набор снаряжения: каска, система, 2 муфтованных HMS, 3 муфтованных карабина, 5 карабинов без муфты, ATC, прусик 7 мм, 2 корделета, 2 петли, самостраховка. На льду/снегу: кошки + 2 ледобура.'
WHERE title = '14.6. Проблемы и решения';

-- 4. Добавляем новые разделы в Главу 14 (детальные техники из книги)

INSERT INTO kg_nodes (title, content, category, level, parent_id) VALUES
(
  '14.7. Снаряжение для ПСР',
  'Минимальный личный набор: каска, страховочная система, 2 карабина муфтованных HMS, 3 муфтованных карабина, 5 карабинов без муфты, спусковое устройство ATC (Reverso/ATC-XP Guide в режиме автоблокировки), прусик 7 мм (1,2–1,5 м), 2 корделета 7 мм (5–6 м), 2 петли 120–180 см, самостраховка из динамической верёвки. На снегу/льду: кошки, 2 ледобура. Групповое снаряжение двойки: верёвка single 50–70 м, петли, оттяжки. ЗАПРЕЩЕНО для самостраховки: петли из Dyneema, стропы, Daisy Chain, клифы. Дополнительное снаряжение при его наличии: блок-ролик, механический зажим типа жумар, Gri-Gri, Mini Traction — значительно облегчают работу. Всё снаряжение должно соответствовать стандартам CE, UIAA.',
  'спасработы', 2, ch14_id
),
(
  '14.8. Спасение из ледниковой трещины',
  'Ключевое условие — правильная подготовка связки: дистанция двойки 15 м, тройки 7 м (на малых ледниках — меньше). Узлы «восьмёрка» каждые 1,5–2 м снижают нагрузку на страхующего при срыве. У каждого — два схватывающих узла аварийной системы (как для подъёма по верёвке). Страховочная верёвка всегда через поясную систему (не только через грудную обвязку). Сценарий 1 (двойка, 15 м дистанция, 17–18 м запаса у спасателя): спасатель задерживает срыв → организует станцию (ледобур или импровизированная) → Z-полиспаст 3:1 → при необходимости 5:1 или 7:1 → обработать край трещины (снежный гробик 1–1,5 м) → опустить конец верёвки. Сценарий 2 (тройка, 7 м дистанция, 15 м запаса): средний или замыкающий организует станцию → полиспаст 2:1 → при тяжёлом пострадавшем 6:1. Подход к краю трещины без страховки опасен — край может быть карнизом!',
  'техника', 2, ch14_id
),
(
  '14.9. Методика обучения ПСР',
  'Полный курс «ПСР в малой группе» (С. Веденин, ФАР 2014): 6–8 дней, 48–64 уч. ч., из них 2 дня — работа в ледниковых трещинах. Требования к месту: рельеф 5–25 м, станции сверху и снизу, ровная площадка для отработки. Требования к студентам: базовые навыки — узлы, страховка, спуск/подъём по верёвке. 1 инструктор на 8 студентов (базовый) или 6 (сложные сценарии). Обучение парами, сложные приёмы — сначала на ровной площадке. Программа: узлы → блокировка СУ → УИАА + узел мула → спуск с самостраховкой → передача страховки → транспортировка пострадавшего → полиспасты → комплексные сценарии. Зачётный сценарий за ≤40 минут без недопустимых ошибок. Система оценки: «Думай!» (ошибка в безопасной ситуации) и «Стоп!» (опасная ситуация). Максимум 100 баллов, зачёт от 70.',
  'спасработы', 2, ch14_id
);

-- 5. Обновляем описание самой Главы 14
UPDATE kg_nodes SET content =
'Организация спасательных работ в связке-двойке или тройке на сложном горном рельефе. На основе методического пособия ФАР «ПСР в малой группе» (С. Веденин, 2014). Охватывает: стратегию и тактику, передачу страховки, узлы, подход к пострадавшему, спуск и подъём, полиспасты, спасение из трещины и методику обучения.'
WHERE title = 'Глава 14. Спасательные работы в малой группе';

END $$;
